/bin/bash -lc "cat >> test/units/executor/module_common/test_module_common.py <<'EOF'


@pytest.mark.parametrize('source, expected', [
    (b'print(1)\\n', (None, [])),
    (b'#"'!/opt/venv/bin/python -I -u'"\\nprint(1)\\n', ('/opt/venv/bin/python', ['-I', '-u'])),
    (b'#"'!/usr/bin/env "python3.8" -u'"\\n', ('/usr/bin/env', ['python3.8', '-u'])),
])
def test_extract_interpreter_from_first_line(source, expected):
    assert amc._extract_interpreter(source) == expected


def test_get_shebang_preserves_specific_python_and_args(templar):
    assert amc._get_shebang('/opt/venv/bin/python3.8', {}, templar, args=('-I', '-u')) == (
        '#"'!/opt/venv/bin/python3.8 -I -u'"', '/opt/venv/bin/python3.8')


def test_get_shebang_preserves_non_python_and_args(templar):
    assert amc._get_shebang('/usr/bin/ruby', {}, templar, args=('-w',)) == (
        '#"'!/usr/bin/ruby -w'"', '/usr/bin/ruby')
EOF
pytest -q test/units/executor/module_common/test_module_common.py -k 'extract_interpreter_from_first_line or get_shebang_preserves' "

